// SUPABASE — using the official SDK now (see src/supabaseClient.js).
// Handles sessions/tokens correctly, unlike the raw fetch() calls
// we started with, which don't manage auth state at all.
// ============================================================
import { supabase } from "./supabaseClient";

async function fetchSprings() {
  const { data, error } = await supabase
    .from("springs")
    .select("*")
    .eq("status", "verified");

  if (error) throw error;

  // Map snake_case DB columns to the camelCase shape the UI already
  // expects, so none of the existing components need to change.
  return data.map((r) => ({
    id: r.id,
    name: r.name,
    region: r.region,
    lat: Number(r.lat),
    lng: Number(r.lng),
    walkMin: r.walk_min || 0,
    water: r.water_status,
    crowded: r.crowd_level,
    shade: r.shade,
    toddler: r.toddler_friendly,
    parking: r.parking,
    parkingType: r.parking_type || null,
    stroller: r.stroller_friendly,
    easyAccess: r.easy_access,
    toilets: r.toilets,
    seating: r.seating,
    depthText: r.depth_text || null,
    picnicTables: r.picnic_tables,
    bbqArea: r.bbq_area,
    lastStatusUpdate: r.last_status_update || null,
    paid: r.paid,
    wheelchair: r.wheelchair_accessible,
    hours: r.hours || "",
    bestSeason: r.best_season || "",
    notes: r.notes || "",
    photo: r.main_photo_url || null,
    distanceKm: null, // computed client-side once real geolocation is wired in
    locationStatus: r.location_status || "estimated",
    locationConfidence: r.confidence || null,
    coordinateStatus: r.coordinate_status || null,
    googleMapsUrl: r.google_maps_url || null,
    googleDestinationType: r.google_destination_type || null,
    wazeUrl: r.waze_url || null,
    wazePoiName: r.waze_poi_name || null,
    wazeDestinationType: r.waze_destination_type || null,
  }));
}

async function sendMagicLink(email) {
  const { error } = await supabase.auth.signInWithOtp({
    email,
    options: { emailRedirectTo: window.location.origin },
  });
  if (error) throw error;
}

async function signOut() {
  await supabase.auth.signOut();
}

async function submitSpringUpdate(springId, water, crowded, note) {
  const { error } = await supabase.rpc("submit_spring_update", {
    p_spring_id: springId,
    p_water_status: water,
    p_crowd_level: crowded,
    p_note: note,
  });
  if (error) throw error;
}

