function WaterVial({ level, size = 40 }) {
  const w = WATER_LEVELS[level];
  const h = size * 1.4;
  const fillH = h * w.fill;
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
      <svg width={size} height={h} viewBox={`0 0 ${size} ${h}`}>
        <rect x="1" y="1" width={size - 2} height={h - 2} rx={size / 4} fill="#fff" stroke={INK} strokeOpacity="0.15" strokeWidth="1.5" />
        <clipPath id={`clip-${level}-${size}`}>
          <rect x="1" y="1" width={size - 2} height={h - 2} rx={size / 4} />
        </clipPath>
        <rect
          x="0"
          y={h - fillH}
          width={size}
          height={fillH}
          fill={w.color}
          clipPath={`url(#clip-${level}-${size})`}
        />
      </svg>
      <span className="ma-mono" style={{ fontSize: 10, fontWeight: 700, color: w.color }}>{w.label}</span>
    </div>
  );
}

