function PhotoLightbox({ photos, startIndex, onClose }) {
  const [index, setIndex] = useState(startIndex);
  const touchStartX = useRef(null);

  const hasPrev = index > 0;
  const hasNext = index < photos.length - 1;
  const goPrev = (e) => {
    e.stopPropagation();
    if (hasPrev) setIndex((i) => i - 1);
  };
  const goNext = (e) => {
    e.stopPropagation();
    if (hasNext) setIndex((i) => i + 1);
  };

  const onTouchStart = (e) => {
    touchStartX.current = e.touches[0].clientX;
  };
  const onTouchEnd = (e) => {
    if (touchStartX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchStartX.current;
    if (dx > 50) goPrev(e);
    else if (dx < -50) goNext(e);
    touchStartX.current = null;
  };

  return (
    <div
      onClick={onClose}
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
      style={{ position: "absolute", inset: 0, background: "rgba(10,15,14,0.97)", zIndex: 20, display: "flex", alignItems: "center", justifyContent: "center" }}
    >
      <button
        onClick={onClose}
        style={{ position: "absolute", top: 16, insetInlineEnd: 16, zIndex: 2, background: "rgba(255,255,255,0.15)", border: "none", borderRadius: 10, width: 36, height: 36, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
      >
        <X size={20} color="#fff" />
      </button>

      {photos.length > 1 && (
        <div className="ma-mono" style={{ position: "absolute", top: 20, insetInlineStart: 20, color: "#fff", fontSize: 12, background: "rgba(255,255,255,0.15)", borderRadius: 20, padding: "4px 10px" }}>
          {index + 1} / {photos.length}
        </div>
      )}

      {hasPrev && (
        <button
          onClick={goPrev}
          style={{ position: "absolute", left: 8, top: "50%", transform: "translateY(-50%)", zIndex: 2, background: "rgba(255,255,255,0.15)", border: "none", borderRadius: "50%", width: 40, height: 40, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
        >
          <ArrowLeft size={20} color="#fff" />
        </button>
      )}
      {hasNext && (
        <button
          onClick={goNext}
          style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", zIndex: 2, background: "rgba(255,255,255,0.15)", border: "none", borderRadius: "50%", width: 40, height: 40, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
        >
          <ArrowRight size={20} color="#fff" />
        </button>
      )}

      <img
        src={photos[index]}
        alt=""
        style={{ width: "100%", height: "100%", objectFit: "contain" }}
        onClick={(e) => e.stopPropagation()}
      />
    </div>
  );
}

