const PARKING_LABELS = {
  official: "חניה מסודרת",
  dirt_any: "חניה לא סלולה",
  dirt_4x4: "גישה ב-4X4 בלבד",
  none: "אין חניה",
};

function parkingLabel(spring) {
  if (spring.parkingType && PARKING_LABELS[spring.parkingType]) {
    return PARKING_LABELS[spring.parkingType];
  }
  return spring.parking ? "יש" : "אין";
}

function lastUpdateLabel(lastStatusUpdate) {
  if (!lastStatusUpdate) return "אין עדכונים עדיין";
  const days = Math.floor((Date.now() - new Date(lastStatusUpdate).getTime()) / 86400000);
  if (days <= 0) return "היום";
  if (days === 1) return "אתמול";
  return `לפני ${days} ימים`;
}

function seatingLabel(spring) {
  if (spring.picnicTables === null && spring.bbqArea === null) {
    return spring.seating ? "יש" : "אין";
  }
  if (spring.picnicTables && spring.bbqArea) return "שולחנות ומנגל";
  if (spring.picnicTables) return "שולחנות פיקניק";
  if (spring.bbqArea) return "אזור מנגל";
  return "אין";
}

function SpringDetail({ spring, onBack, onUpdate }) {
  const w = WATER_LEVELS[spring.water];
  const crowdLabel = { empty: "רגוע", normal: "בינוני", busy: "עמוס" }[spring.crowded];
  const [lightboxIndex, setLightboxIndex] = useState(null);
  const [showCommentsNotice, setShowCommentsNotice] = useState(false);

  // Hero photo + "recent uploads" all currently point at the same real
  // photo (honest placeholder until real crowdsourced photos exist per
  // spring) — built as a real array so the navigation mechanism works
  // correctly once distinct photos are added later.
  const photos = spring.photo ? [spring.photo, spring.photo, spring.photo, spring.photo] : [];

  return (
    <div style={{ height: "100%", background: STONE, display: "flex", flexDirection: "column" }}>
      <FontStyles />
      <div className="ma-scroll" style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
        <div style={{ position: "relative" }}>
          <button
            onClick={() => photos.length && setLightboxIndex(0)}
            style={{ width: "100%", padding: 0, border: "none", background: "none", cursor: photos.length ? "pointer" : "default", display: "block" }}
          >
            <SpringVisual spring={spring} index={spring.id} height={220} radius="0" />
          </button>
          <button
            onClick={onBack}
            style={{ position: "absolute", top: 16, insetInlineStart: 16, background: "rgba(255,255,255,0.9)", border: "none", borderRadius: 10, width: 36, height: 36, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}
          >
            <ArrowRight size={18} color={INK} />
          </button>
          <div style={{ position: "absolute", bottom: -26, insetInlineEnd: 20, background: "#fff", borderRadius: 16, padding: "8px 12px", boxShadow: "0 4px 14px rgba(31,42,40,0.15)" }}>
            <WaterVial level={spring.water} size={30} />
          </div>
        </div>

        <div style={{ padding: "34px 20px 0" }}>
          <div className="ma-display" style={{ fontSize: 26, fontWeight: 700, color: INK }}>{spring.name}</div>
          <div className="ma-mono" style={{ fontSize: 12, color: "#8A8478", marginTop: 4, display: "flex", alignItems: "center", gap: 4 }}>
            <MapPin size={12} /> {spring.region} · {spring.distanceKm} ק״מ ממך
          </div>
          {spring.locationStatus === "estimated" && (
            <div
              className="ma-mono"
              style={{ fontSize: 10, color: "#8A5A00", background: "#FFF3D6", display: "inline-block", borderRadius: 999, padding: "3px 10px", marginTop: 6 }}
            >
              מיקום משוער — טרם אומת
            </div>
          )}
        </div>

        <RecentPhotosRow photos={photos} onOpenPhoto={setLightboxIndex} />

        <div style={{ padding: "10px 20px 20px" }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 10 }}>
            <InfoBox icon={Trees} label="צל" value={spring.shade ? "כן" : "לא"} />
            <InfoBox icon={Car} label="חניה" value={parkingLabel(spring)} />
            <InfoBox icon={Footprints} label="הליכה" value={`${spring.walkMin} דק׳`} />
            <InfoBox icon={Smile} label="פעוטות" value={spring.toddler ? "מתאים לפעוטות" : "לא מתאים לפעוטות"} />
            <InfoBox icon={Waves} label="עומק" value={spring.depthText ? `${spring.depthText} מ׳` : "לא ידוע"} />
            <InfoBox icon={Users} label="עומס" value={crowdLabel} />
            <InfoBox icon={Toilet} label="שירותים" value={spring.toilets ? "יש" : "אין"} />
            <InfoBox icon={UtensilsCrossed} label="ישיבה" value={seatingLabel(spring)} />
            <InfoBox icon={Camera} label="עדכון אחרון" value={lastUpdateLabel(spring.lastStatusUpdate)} />
            <InfoBox icon={CircleDollarSign} label="כניסה" value={spring.paid ? "בתשלום" : "חינם"} />
            <InfoBox icon={Accessibility} label="נגישות" value={spring.wheelchair ? "נגיש" : "לא נגיש"} />
            <InfoBox icon={Clock} label="שעות" value={spring.hours || "ללא הגבלה"} />
          </div>

          {spring.bestSeason && (
            <div className="ma-body" style={{ marginTop: 14, fontSize: 12, color: "#8A8478" }}>
              <strong>עונה מומלצת:</strong> {spring.bestSeason}
            </div>
          )}

          {spring.notes && (
            <div
              className="ma-body"
              style={{ marginTop: 10, fontSize: 12, color: "#8A5A00", background: "#FFF3D6", border: `1px solid ${SUN}`, borderRadius: 10, padding: "10px 12px", lineHeight: 1.5 }}
            >
              {spring.notes}
            </div>
          )}
        </div>
      </div>

      <div style={{ padding: "4px 20px 20px", flexShrink: 0 }}>
        {["govmap_verified", "independently_verified"].includes(spring.coordinateStatus) ? (
          <>
            <div style={{ display: "flex", justifyContent: "center", gap: 36, padding: "4px 0" }}>
              <a
                href={spring.googleMapsUrl || `https://www.google.com/maps/dir/?api=1&destination=${spring.lat},${spring.lng}`}
                target="_blank"
                rel="noopener noreferrer"
                style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, textDecoration: "none" }}
              >
                <div style={{ width: 52, height: 52, borderRadius: 999, background: "#0F9D58", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 4px 10px rgba(15,157,88,0.3)" }}>
                  <Navigation size={22} color="#fff" />
                </div>
                <span dir="ltr" className="ma-body" style={{ fontSize: 12, fontWeight: 600, color: INK }}>Google Maps</span>
              </a>
              <a
                href={spring.wazeUrl || `https://waze.com/ul?ll=${spring.lat},${spring.lng}&navigate=yes`}
                target="_blank"
                rel="noopener noreferrer"
                style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, textDecoration: "none" }}
              >
                <div style={{ width: 52, height: 52, borderRadius: 999, background: "#33CCFF", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 4px 10px rgba(51,204,255,0.3)" }}>
                  <Navigation size={22} color="#fff" />
                </div>
                <span dir="ltr" className="ma-body" style={{ fontSize: 12, fontWeight: 600, color: INK }}>Waze</span>
              </a>
            </div>
            {(spring.googleDestinationType === "parking" || spring.googleDestinationType === "access" ||
              spring.wazeDestinationType === "parking" || spring.wazeDestinationType === "access") && (
              <div className="ma-body" style={{ textAlign: "center", fontSize: 11, color: "#8A8478", marginTop: 4 }}>
                הניווט מוביל לחניה/גישה, לא ישירות למעיין
              </div>
            )}
          </>
        ) : (
          <div className="ma-body" style={{ textAlign: "center", fontSize: 12, color: "#8A8478", padding: "8px 0" }}>
            מיקום המעיין טרם אומת מספיק לצורך ניווט
          </div>
        )}
        <button
          onClick={onUpdate}
          className="ma-body"
          style={{ width: "100%", background: SUN, color: "#fff", border: "none", borderRadius: 999, padding: "16px 0", fontSize: 15, fontWeight: 800, cursor: "pointer" }}
        >
          עדכנו את מצב המעיין
        </button>
        <button
          onClick={() => setShowCommentsNotice(true)}
          className="ma-body"
          style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6, background: "none", border: "none", color: "#9aa89f", fontSize: 12, fontWeight: 600, padding: "2px 0", cursor: "pointer" }}
        >
          <MessageCircle size={13} />
          <span>{spring.commentsCount ?? 0} תגובות</span>
        </button>
        {showCommentsNotice && (
          <div className="ma-body" style={{ fontSize: 11, color: "#8A5A00", textAlign: "center" }}>
            תגובות עדיין לא זמינות — בקרוב.
          </div>
        )}
      </div>

      {lightboxIndex !== null && <PhotoLightbox photos={photos} startIndex={lightboxIndex} onClose={() => setLightboxIndex(null)} />}
    </div>
  );
}

function Select({ label, options, value, onChange }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <div className="ma-body" style={{ fontSize: 13, fontWeight: 600, color: INK, marginBottom: 8 }}>{label}</div>
      <div style={{ display: "flex", gap: 8 }}>
        {options.map((o) => (
          <button
            key={o.value}
            onClick={() => onChange(o.value)}
            className="ma-body"
            style={{
              flex: 1,
              padding: "12px 6px",
              borderRadius: 12,
              border: `2px solid ${value === o.value ? SPRING : "#DCD5C4"}`,
              background: value === o.value ? `${SPRING}14` : "#fff",
              color: value === o.value ? SPRING : INK,
              fontSize: 13,
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function UpdateFlow({ spring, onClose, onSubmitted, onSubmit, session, onRequireLogin }) {
  const [water, setWater] = useState(spring.water);
  const [crowd, setCrowd] = useState(spring.crowded);
  const [note, setNote] = useState("");
  const [done, setDone] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async () => {
    if (!session) {
      onRequireLogin();
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      await submitSpringUpdate(spring.id, water, crowd, note);
      onSubmit(spring.id, { water, crowded: crowd, note });
      setDone(true);
    } catch (err) {
      setError("שמירת העדכון נכשלה. נסו שוב.");
    }
    setSubmitting(false);
  };

  if (done) {
    return (
      <div style={{ position: "absolute", inset: 0, background: STONE, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 30, textAlign: "center", zIndex: 10 }}>
        <FontStyles />
        <div style={{ width: 64, height: 64, borderRadius: "50%", background: `${MOSS}22`, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 16 }}>
          <Check size={30} color={MOSS} />
        </div>
        <div className="ma-display" style={{ fontSize: 19, fontWeight: 700, color: INK, marginBottom: 6 }}>תודה על העדכון!</div>
        <div className="ma-body" style={{ fontSize: 13, color: "#8A8478", marginBottom: 24 }}>המידע החדש כבר מוצג לכולם.</div>
        <button onClick={onSubmitted} className="ma-body" style={{ background: SPRING, color: "#fff", border: "none", borderRadius: 12, padding: "12px 28px", fontSize: 14, fontWeight: 600, cursor: "pointer" }}>
          חזרה
        </button>
      </div>
    );
  }

  return (
    <div style={{ position: "absolute", inset: 0, background: STONE, display: "flex", flexDirection: "column", zIndex: 10 }}>
      <FontStyles />
      <div style={{ flexShrink: 0, padding: "18px 20px 10px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div className="ma-display" style={{ fontSize: 18, fontWeight: 700, color: INK }}>עדכון · {spring.name}</div>
        <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: INK }}>
          <X size={20} />
        </button>
      </div>

      <div className="ma-scroll" style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "10px 20px" }}>
        <Select
          label="💧 מים"
          value={water}
          onChange={setWater}
          options={[
            { value: "dry", label: "יבש" },
            { value: "low", label: "נמוך" },
            { value: "good", label: "טוב" },
            { value: "full", label: "מלא" },
          ]}
        />
        <Select
          label="👥 עומס"
          value={crowd}
          onChange={setCrowd}
          options={[
            { value: "empty", label: "רגוע" },
            { value: "normal", label: "בינוני" },
            { value: "busy", label: "עמוס" },
          ]}
        />

        <div style={{ marginBottom: 16 }}>
          <div className="ma-body" style={{ fontSize: 13, fontWeight: 600, color: INK, marginBottom: 8 }}>📷 הוספת תמונה</div>
          <button
            className="ma-body"
            style={{
              width: "100%",
              padding: "16px",
              borderRadius: 12,
              border: "2px dashed #DCD5C4",
              background: "#fff",
              color: "#8A8478",
              fontSize: 13,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 6,
              cursor: "pointer",
            }}
          >
            <Camera size={22} />
            הוספת תמונה (רשות)
          </button>
        </div>

        <div style={{ marginBottom: 8 }}>
          <div className="ma-body" style={{ fontSize: 13, fontWeight: 600, color: INK, marginBottom: 8 }}>הערות נוספות (רשות)</div>
          <textarea
            value={note}
            onChange={(e) => setNote(e.target.value)}
            rows={3}
            placeholder="למשל: השביל חלקלק, כדאי נעליים סגורות..."
            className="ma-body"
            style={{ width: "100%", boxSizing: "border-box", padding: 12, borderRadius: 12, border: "1.5px solid #DCD5C4", fontSize: 13, resize: "vertical", outline: "none" }}
          />
        </div>
      </div>

      <div style={{ padding: 20, flexShrink: 0 }}>
        {!session && (
          <div className="ma-body" style={{ fontSize: 12, color: "#8A5A00", background: "#FFF3D6", border: `1px solid ${SUN}`, borderRadius: 10, padding: "10px 12px", marginBottom: 10 }}>
            צריך להתחבר כדי לפרסם עדכון — נעביר אתכם לכניסה.
          </div>
        )}
        {error && (
          <div className="ma-body" style={{ fontSize: 12, color: "#B5652E", marginBottom: 10 }}>{error}</div>
        )}
        <button
          onClick={handleSubmit}
          disabled={submitting}
          className="ma-body"
          style={{ width: "100%", background: SPRING, color: "#fff", border: "none", borderRadius: 14, padding: "15px", fontSize: 15, fontWeight: 700, cursor: submitting ? "default" : "pointer", opacity: submitting ? 0.7 : 1 }}
        >
          {submitting ? "שולח..." : session ? "פרסום העדכון" : "כניסה לחשבון"}
        </button>
      </div>
    </div>
  );
}

export default function MaayanotApp() {
  const [screen, setScreen] = useState("splash");
  const [springs, setSprings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(null);
  const [activeSpringId, setActiveSpringId] = useState(null);
  const [showUpdate, setShowUpdate] = useState(false);
  const [session, setSession] = useState(null);

  useEffect(() => {
    fetchSprings()
      .then((data) => {
        setSprings(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setLoadError("לא הצלחנו לטעון את הנתונים. בודקים גרסת הדגמה מקומית.");
        setSprings(SPRINGS); // fallback to mock data so the app stays usable
        setLoading(false);
      });
  }, []);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data: listener } = supabase.auth.onAuthStateChange((_event, newSession) => {
      setSession(newSession);
      // A successful login while mid-update-flow should return the
      // person straight back to what they were doing, not strand them.
      if (newSession && screen === "login") setScreen("profile");
    });
    return () => listener.subscription.unsubscribe();
  }, [screen]);

  const activeSpring = springs.find((s) => s.id === activeSpringId) || null;

  const handleUpdateSubmit = (springId, changes) => {
    setSprings((prev) =>
      prev.map((s) =>
        s.id === springId
          ? { ...s, water: changes.water, crowded: changes.crowded, lastUpdateNote: changes.note || s.lastUpdateNote }
          : s
      )
    );
  };

  if (loading) {
    return (
      <div
        dir="rtl"
        style={{
          width: "100%", maxWidth: 400, height: "min(760px, calc(100dvh - 16px))", margin: "0 auto",
          background: STONE, borderRadius: 22, display: "flex", alignItems: "center", justifyContent: "center",
          boxShadow: "0 20px 60px rgba(31,42,40,0.25)", border: "6px solid #E3DCC9",
        }}
      >
        <FontStyles />
        <div className="ma-body" style={{ color: INK }}>טוען מעיינות...</div>
      </div>
    );
  }

  return (
    <div
      dir="rtl"
      style={{
        width: "100%",
        maxWidth: 400,
        height: "min(760px, calc(100dvh - 16px))",
        margin: "0 auto",
        background: STONE,
        borderRadius: 22,
        overflow: "hidden",
        position: "relative",
        boxShadow: "0 20px 60px rgba(31,42,40,0.25)",
        border: "6px solid #E3DCC9",
      }}
    >
      {loadError && (
        <div className="ma-mono" style={{ position: "absolute", top: 0, insetInlineStart: 0, insetInlineEnd: 0, zIndex: 30, background: "#FFF3D6", color: "#8A5A00", fontSize: 10, textAlign: "center", padding: "4px 8px" }}>
          {loadError}
        </div>
      )}
      {screen === "splash" && <Splash onStart={() => setScreen("browse")} />}
      {screen === "browse" && (
        <BrowseScreen
          onGoTab={(tab) => setScreen(tab)}
          onOpenSpring={(s) => {
            setActiveSpringId(s.id);
            setScreen("detail");
          }}
          springs={springs}
        />
      )}
      {screen === "detail" && activeSpring && (
        <SpringDetail spring={activeSpring} onBack={() => setScreen("browse")} onUpdate={() => setShowUpdate(true)} />
      )}
      {screen === "submit" && <SubmitScreen onGoTab={(tab) => setScreen(tab)} />}
      {screen === "login" && <LoginScreen onGoTab={(tab) => setScreen(tab)} />}
      {screen === "profile" && (
        <ProfileScreen
          onGoTab={(tab) => setScreen(tab)}
          onLogout={async () => {
            await signOut();
            setScreen("splash");
          }}
          springs={springs}
          session={session}
        />
      )}
      {showUpdate && activeSpring && (
        <UpdateFlow
          spring={activeSpring}
          onClose={() => setShowUpdate(false)}
          onSubmitted={() => setShowUpdate(false)}
          onSubmit={handleUpdateSubmit}
          session={session}
          onRequireLogin={() => {
            setShowUpdate(false);
            setScreen("login");
          }}
        />
      )}
    </div>
  );
}
